  })

  it('rejects a conflicting URL and --site', async () => {
    await run(['issue', `${site.siteUrl}/browse/ENG-123`, '--site', 'other'], {
      'jira.status': { sites: [site, { ...site, id: 'other', siteUrl: 'https://other.example' }] }
    })
